const Digit:React.FC<{x:number;y:number;length?:number;bend?:number;cut?:boolean;fat?:number;wood?:boolean;angle?:number;two?:boolean}>=({x,y,length=1,bend=0,cut=false,fat=1,wood=false,angle=0,two=false})=>{
 const w=27*fat, col=wood?'url(#bone)':'url(#skin)';
 const segment=(l:number,tip=false)=><><path d={`M${-w} 6Q${-w-3} ${-l*.5} ${-w+5} ${-l+12}Q0 ${-l-14} ${w-5} ${-l+12}Q${w+3} ${-l*.5} ${w} 6Z`} fill={col}/><path d={`M${-w+7} -6q${w-7} -9 ${2*w-14} 0M${-w+10} -12q${w-10} -7 ${2*w-20} 0`} stroke="#5f3c2a" strokeOpacity=".4" strokeWidth={2} fill="none"/>{!wood&&<path d={`M${-w} 4V${-l+12}Q0 ${-l-14} ${w} ${-l+12}V4Z`} fill="url(#pores)"/>}{tip&&!cut&&<rect x={-w*.64} y={-l+9} width={w*1.28} height={l*.46} rx={10} fill="url(#nail)" stroke="#d8ad8c" strokeWidth={1.4}/>}<path d={`M${-w+5} -18V${-l+15}`} stroke="#edc39a" strokeOpacity=".35" strokeWidth={3} fill="none"/>{cut&&<><path d={`M-10-8V${-l+18}Q0 ${-l+6} 10 ${-l+18}V-8Z`} fill="url(#bone)"/><path d={`M-15 8V${-l+8}`} stroke="url(#tendon)" strokeWidth={7} fill="none"/><path d={`M-21 ${-l+20}q20 10 42 0`} stroke="#a9bac0" strokeWidth={5} fill="none"/></>}</>;
 return <g transform={`translate(${x} ${y}) rotate(${angle}) scale(1 ${length})`}><g transform={`rotate(${bend})`}><circle r={w} fill={col}/>{segment(105)}<g transform={`translate(0 -100) rotate(${bend*.85})`}><circle r={w} fill={col}/>{segment(76,two)}{!two&&<g transform={`translate(0 -71) rotate(${bend*.7})`}><circle r={w} fill={col}/>{segment(65,true)}</g>}</g></g></g>;
};
const Hand:React.FC<{x?:number;y?:number;k?:number;bend?:number;cut?:boolean;fat?:number;wood?:boolean;threads?:boolean}>=({x=540,y=1120,k=1.45,bend=0,cut=false,fat=1,wood=false,threads=false})=><g transform={`translate(${x} ${y}) scale(${k})`}>
 <ellipse cx={5} cy={95} rx={160} ry={45} fill="#000" opacity=".18"/>
 <path d="M-65 385L-83 176Q-160 100-146-24L-130-155Q-120-180-65-160L32-188Q115-170 132-82L126 86Q105 147 66 178L57 385Z" fill={wood?'url(#bone)':'url(#skin)'} stroke="#8d593c" strokeWidth={2}/>
 <path d="M-65 385L-83 176Q-160 100-146-24L-130-155Q-120-180-65-160L32-188Q115-170 132-82L126 86Q105 147 66 178L57 385Z" fill="url(#pores)"/>
 <path d="M-125-93l15 7m57-27l18 4m40 0l20 5m48 37l13 4M-76 145q60-15 126-2" stroke="#65432e" strokeWidth={3} fill="none" opacity=".6"/>
 <path d="M-124-70Q-135 65-90 139" stroke="#dfb58a" strokeWidth={7} opacity=".25" fill="none"/>
 {[-102,-38,30,91].map((xx,i)=><Digit key={i} x={xx} y={[-106,-145,-132,-72][i]} length={[1,1.12,1.05,.82][i]} bend={bend*(i%2?1:.9)} cut={cut} fat={fat} wood={wood} angle={[-9,-3,4,15][i]}/>)}
 <Digit x={-110} y={73} length={.77} bend={bend*.4} cut={cut} fat={fat} wood={wood} angle={-57} two/>
 {cut&&<>{[-85,-35,25,78].map((xx,i)=><g key={i}><path d={`M${xx} -110L${xx*.25} 188L${xx*.2} 390`} stroke="url(#bone)" strokeWidth={14} fill="none"/><path d={`M${xx-13} -122Q${xx-35} 40 ${xx*.23-12} 178L${xx*.23-12} 390`} stroke={threads?lime:pearl} strokeWidth={6} fill="none"/>{i<3&&<path d={`M${xx} 65Q${xx+40} 90 ${xx*.25} 145Q${xx-25} 110 ${xx} 65`} fill="url(#muscle)"/>}</g>)}<path d="M-120 0Q-55-25-45 100Q-95 145-120 0" fill="url(#muscle)" opacity=".9"/></>}
 </g>;
