export const SFX=[{t:T(0),s:'whoosh_01'},{t:en('músculo'),s:'pop_01'},{t:en('cierra'),s:'click_01'},{t:en('antebrazo'),s:'whoosh_02'},{t:en('codo'),s:'tick_01'},{t:en('truco'),s:'tick_02'},{t:en('músculos'),s:'whoosh_03'},{t:en('lejos'),s:'click_02'},{t:en('cordones'),s:'pop_02'},{t:en('tendones'),s:'ding_01'},{t:en('muñeca'),s:'whoosh_04'},{t:en('palma'),s:'click_03'},{t:en('huesitos'),s:'click_04'},{t:en('encoge'),s:'tick_01'},{t:en('dobla'),s:'pop_03'},{t:en('marioneta'),s:'whoosh_05'},{t:en('hilos'),s:'click_01'},{t:en('brazo'),s:'click_02'},{t:en('pequeños'),s:'tick_02'},{t:en('ninguno'),s:'ding_02'},{t:en('gordos'),s:'pop_01'},{t:en('salchichas'),s:'pop_02'},{t:en('piano'),s:'click_03'},{t:en('aguja'),s:'click_04'},{t:en('hilos',2),s:'ding_03'},{t:en('fuertes'),s:'pop_03'}];

export const Escena:React.FC=()=>{
 const {s}=useS();const n=Math.max(0,cuts.findIndex((t,i)=>s>=t&&(i===12||s<cuts[i+1])));const a=cuts[n],b=cuts[n+1]??DUR,p=clamp((s-a)/(b-a));
 const progress=(t:number,end:number)=>clamp((s-t)/Math.max(.05,end-t));
 const pulse=(1-Math.cos((s-a)*2.1))*.5;
 const bg=(inside=false)=><><rect width={1080} height={1920} fill={inside?'url(#inside)':'url(#table)'}/>{!inside&&<rect width={1080} height={1920} fill="url(#grain)"/>}<ellipse cx={540} cy={1000} rx={500} ry={700} fill="url(#glow)"/></>;
 const outer=<>{bg()}<Hand bend={pulse*20} y={1080} k={1.5}/></>;
 let scene:React.ReactNode;
 if(n===0)scene=<>{outer}{s>=en('músculo')&&<><circle cx={490+p*100} cy={670} r={125} fill="#d8ff80" fillOpacity=".06" stroke={lime} strokeWidth={6}/><path d={`M${580+p*100} 760l90 90`} stroke={lime} strokeWidth={15} strokeLinecap="round"/>{tag(780,580,'0 músculos',lime,38)}</>}</>;
 else if(n===1)scene=<>{bg()}<g transform={`translate(0 ${p*250})`}><Hand x={570} y={800} k={1.13} bend={pulse*38}/><g transform="translate(40 420) scale(.9)"><Forearm s={s}/></g></g></>;
 else if(n===2)scene=<>{bg()}<g transform={`translate(-50 130) scale(1.15)`}><Forearm s={s}/></g><ellipse cx={410} cy={860} rx={180+pulse*15} ry={140} fill="none" stroke={lime} strokeWidth={6} opacity={.5+pulse*.4}/></>;
 else if(n===3)scene=<Entrar t={en('músculos')} x={475} y={900} dur={.8} zoom={12} fuera={<>{bg()}<Forearm s={s}/></>} dentro={<>{bg(true)}<Forearm s={s} cut contract={pulse*.3}/>{tag(825,770,'aquí',lime,42)}</>}/>;
 else if(n===4)scene=<>{bg(true)}<g transform={`translate(0 ${-60-p*210})`}><Forearm s={s} cut contract={pulse*.25}/>{[-1,0,1].map(i=><g key={i}><path d={`M${510+i*60} 1410Q${450+i*70} 1550 ${530+i*75} 1780`} stroke={pearl} strokeWidth={18} fill="none"/><path d={`M${505+i*60} 1420Q${455+i*70} 1550 ${525+i*75} 1770`} stroke="#fff" strokeOpacity=".4" strokeWidth={4} fill="none"/></g>)}</g></>;
 else if(n===5)scene=<>{bg(true)}<g transform={`translate(540 1000) scale(${1.3+p*.25}) translate(-540 -1000)`}><Hand y={990+p*180} cut k={1.55}/><path d="M410 1465Q530 1520 660 1465" stroke="#9c959e" strokeWidth={35} fill="none"/><path d="M410 1447Q530 1502 660 1447" stroke="#dfd7d3" strokeWidth={5} fill="none"/><circle cx={510} cy={1500-p*780} r={25} fill={lime} opacity=".7"/></g></>;
 else if(n===6){const pull=progress(en('encoge'),en('dobla'));scene=<>{bg(true)}<g transform="translate(160 260) scale(.7)"><g transform="translate(0 2545) scale(1 -1)"><Forearm s={s} cut contract={pull}/></g><Hand y={680} k={1.13} cut bend={pull*45}/><path d="M480 1710Q440 1420 530 1110L465 575" stroke={lime} strokeWidth={7} fill="none" opacity=".7"/></g></>;}
 else if(n===7)scene=<>{bg()}<path d="M360 560H800M580 500V630" stroke="#bea27b" strokeWidth={27} strokeLinecap="round"/><g transform={`translate(0 ${-pulse*25})`}><Hand wood k={1.4} y={1180} bend={pulse*26}/>{[-110,-40,30,100].map((x,i)=><path key={i} d={`M${430+i*70} 560L${540+x*1.4} ${810+(i%2)*60}`} stroke={lime} strokeWidth={3} fill="none"/>)}</g><g transform="translate(650 460) rotate(160) scale(.4)"><Hand x={0} y={0} k={1} bend={25}/></g></>;
 else if(n===8)scene=<>{bg(true)}<Hand y={1140} k={1.55} cut bend={pulse*5}/>{s>=en('ninguno')&&tag(795,640,'0',lime,76)}</>;
 else if(n===9)scene=<>{bg()}<Hand y={1100} bend={pulse*15} fat={1+progress(en('dentro'),en('salchichas'))*1.1}/></>;
 else if(n===10){const needle=s>=en('enhebrar');scene=<>{bg()}<g opacity={needle?0:1}>{Array.from({length:11},(_,i)=><g key={i}><rect x={50+i*90} y={1060} width={86} height={340} rx={7} fill={i>3&&i<7?'#cbc58b':'#e4e1d2'} stroke="#7b756f" strokeWidth={3}/>{i%3!==0&&<rect x={106+i*90} y={1060} width={48} height={185} rx={4} fill="#171f27"/>}</g>)}</g>{needle&&<><path d="M760 790L680 1420" stroke="#c4d3d6" strokeWidth={11}/><ellipse cx={755} cy={823} rx={8} ry={27} fill="#263340" stroke="#eff5f1" strokeWidth={4}/><path d="M120 1130Q400 900 650 895Q720 900 690 840" stroke={pearl} strokeWidth={7} fill="none"/></>}<g transform="translate(140 0) rotate(15 540 1000)"><Hand y={1050} k={1.17} fat={2.1} bend={32}/></g><path d="M770 1480l100 100m0-100l-100 100" stroke={lime} strokeWidth={16} strokeLinecap="round"/></>;}
 else if(n===11)scene=<>{bg()}<Hand y={1090} bend={progress(en('cerrar'),en('hilos',2))*42} cut threads k={1.5}/></>;
 else scene=<>{bg()}<Hand y={1050} bend={38+5*pulse} k={1.5}/><path d={`M410 1510Q${420-pulse*15} 1440 450 1370`} stroke="#d1a178" strokeWidth={15} opacity=".4" fill="none"/></>;
